def compute(vars):
    price_per_share = vars["Price per Share"]
    shares_outstanding = vars["Shares Outstanding"]
    market_capitalization = price_per_share * shares_outstanding

    return {
        "value": market_capitalization,
        "trace": {
            "Price per Share": price_per_share,
            "Shares Outstanding": shares_outstanding,
            "output_meta": {
                "currency": "$",
                "scale": None,
                "unit": "$"
            }
        }
    }
